const id = () => crypto.randomUUID();
const stamp = () => new Date().toISOString();
const localDateTime = (value: string) => new Intl.DateTimeFormat("pt-BR", { dateStyle: "short", timeStyle: "short", timeZone: "America/Sao_Paulo" }).format(new Date(value));
const ageOf = (birth: string) => { const d = new Date(`${birth}T12:00:00`); if (!birth || Number.isNaN(d.getTime())) return "—"; const now = new Date(); let age = now.getFullYear() - d.getFullYear(); if (now.getMonth() < d.getMonth() || (now.getMonth() === d.getMonth() && now.getDate() < d.getDate())) age--; return `${age} anos`; };
const noAccent = (s: string) => s.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();

const cpfDigits = (value: string) => value.replace(/\D/g, "");
const validCpf = (value: string) => {
  const cpf = cpfDigits(value); if (!cpf) return true;
  if (cpf.length !== 11 || /^(\d)\1{10}$/.test(cpf)) return false;
  const calc = (base: string, factor: number) => { const sum = [...base].reduce((acc, n) => acc + Number(n) * factor--, 0); const remainder = (sum * 10) % 11; return remainder === 10 ? 0 : remainder; };
  return calc(cpf.slice(0, 9), 10) === Number(cpf[9]) && calc(cpf.slice(0, 10), 11) === Number(cpf[10]);
};
const patientSchema = z.object({
  nome: z.string().trim().min(2, "Informe o nome civil."), nomeSocial: z.string().optional(), nascimento: z.string().min(1, "Informe a data de nascimento."),
  genero: z.string().min(1, "Selecione uma opção."), orientacao: z.string().optional(), racaCor: z.string().optional(), estadoCivil: z.string().optional(), escolaridade: z.string().optional(), profissao: z.string().optional(), religiao: z.string().optional(), naturalidade: z.string().optional(), cpf: z.string().optional().refine((v) => validCpf(v ?? ""), "CPF inválido."), telefone: z.string().optional(), email: z.union([z.string().email("E-mail inválido."), z.literal("")]).optional(), endereco: z.string().optional(), emergenciaNome: z.string().optional(), emergenciaVinculo: z.string().optional(), emergenciaTelefone: z.string().optional(), responsavelLegal: z.string().optional(), modalidadePlano: z.string().optional(),
}).superRefine((data, ctx) => { if (ageOf(data.nascimento).startsWith("0") || Number.parseInt(ageOf(data.nascimento), 10) < 18) { if (!data.responsavelLegal?.trim()) ctx.addIssue({ code: "custom", path: ["responsavelLegal"], message: "Para menores de 18 anos, informe o responsável legal." }); } });
type PatientForm = z.infer<typeof patientSchema>;

